if(sub==='start'||sub==='出发'){if(!s||!s.setup||s.setup.step!=='done'){seal.replyToSender(ctx,msg,'请先 .wjd init 并完成三组选择。');return result();}if(s.step==='active'){seal.replyToSender(ctx,msg,'你已经在城市里。');return result();}s=makeGame(uid,s.name,s,meta);s.metaPoints=meta.points;write(uid,s);await image(ctx,msg,'tutorial',tutorialPayload(s,1),'第一天教程已开启。随时使用 .wjd tutorial 查看进度。');return result();}
if(sub==='tutorial'||sub==='教程'||sub==='guide'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'进入城市后才会开启三日教程。');return result();}const op=String(arg(cmdArgs,2)).toLowerCase();if(op==='off'||op==='关闭'){s.tutorial.enabled=false;write(uid,s);seal.replyToSender(ctx,msg,'教程提示已关闭，使用 .wjd tutorial on 重新开启。');return result();}if(op==='on'||op==='开启'){s.tutorial.enabled=true;write(uid,s);}await image(ctx,msg,'tutorial',tutorialPayload(s,num(op,0)||undefined),'三日教程覆盖近乎所有主要功能。');return result();}
if(sub==='status'||sub==='状态'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'没有进行中的周目。使用 .wjd init。');return result();}const tip=tutorialComplete(s,'status');write(uid,s);await image(ctx,msg,'status',snapshot(s),statusText(s)+tip);return result();}
if(sub==='use'||sub==='使用'||sub==='consume'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const item=arg(cmdArgs,2);const before=Number(s.inventory[item]||0),message=useItem(s,item),tip=Number(s.inventory[item]||0)<before?tutorialComplete(s,'use'):'';write(uid,s);seal.replyToSender(ctx,msg,message+tip);return result();}
if(sub==='inventory'||sub==='bag'||sub==='背包'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const page=Math.max(1,num(arg(cmdArgs,2),1)),tip=tutorialComplete(s,'inventory');write(uid,s);const rows=inventoryRows(s);await image(ctx,msg,'inventory',{name:s.name,day:s.day,page,capacity:carryCapacity(s),weight:carryWeight(s),rows},`背包重量 ${carryWeight(s).toFixed(1)} / ${carryCapacity(s)}。使用 .wjd item [名称] 查看图鉴。${tip}`);return result();}
if(sub==='item'||sub==='物资'||sub==='inspect'){const item=arg(cmdArgs,2);const info=itemInfo(item);const count=s&&s.inventory?Number(s.inventory[item]||0):0;seal.replyToSender(ctx,msg,`【${info.name}】\n分类：${info.use}｜稀有度：${info.rarity}｜重量：${info.weight}\n${info.desc}\n当前持有：${count}`);return result();}
if(sub==='recipes'||sub==='recipe'||sub==='配方'){const page=Math.max(1,num(arg(cmdArgs,2),1)),tip=s&&s.step==='active'?tutorialComplete(s,'recipes'):'';if(s)write(uid,s);const start=(page-1)*8;seal.replyToSender(ctx,msg,(RECIPES.slice(start,start+8).map((r,i)=>`${start+i+1}. ${r.name}：${Object.keys(r.need).map(k=>`${k}×${r.need[k]}`).join('、')} → ${Object.keys(r.out).map(k=>`${k}×${r.out[k]}`).join('、')}\n   ${r.desc}`).join('\n')||'没有更多配方。')+tip);return result();}
if(sub==='craft'||sub==='制作'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}if(!s.atBase){seal.replyToSender(ctx,msg,'制作需要工作空间。先使用 .wjd action 返回。');return result();}const recipeName=arg(cmdArgs,2);const recipe=recipeByName(recipeName)||RECIPES[num(recipeName)-1];if(!recipe){seal.replyToSender(ctx,msg,'请输入配方名称或编号，使用 .wjd recipes 查看。');return result();}const c=craft(s,recipe.name);let tip='';if(c.ok){countAction(s,'制作');const level=gainSkill(s,'制作',4);tip=tutorialComplete(s,'craft')+(level?`\n${level}`:'')+registerDailyAction(s,meta,'制作',{outside:false,eventChance:.08});}write(uid,s);await image(ctx,msg,'status',snapshot(s),c.msg+tip);return result();}
if(sub==='action'||sub==='行动'||sub==='act'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const k=arg(cmdArgs,2),previousDay=s.day,r=action(s,meta,k,arg(cmdArgs,3));const ids={搜刮:'loot',返回:'return',回家:'return',返程:'return',休息:previousDay===1?'rest':(previousDay===2?'rest2':null),侦查:'scout',清剿:'fight',治疗:'heal',移动:'move'};const tip=r.advanced&&ids[k]?tutorialComplete(s,ids[k],previousDay):'';write(uid,s);if(s.dead){await image(ctx,msg,'death',Object.assign({},s.death,{legacyPoints:meta.points,unlock:'可在下一局继续购买新特质。'}),'这一页是你本周目的最后记录。');}else if(s.lastNarrative&&s.lastNarrative.day===s.day&&s.lastNarrative.actionNo===s.dailyActions){await image(ctx,msg,'event',Object.assign({},s.lastNarrative,{timeLabel:timeLabel(s),eventId:`${s.day}-${s.dailyActions}-${s.lastEvent}`,danger:threatBudget(s)+s.fatigue*10>65}),r.message+tip);}else await image(ctx,msg,'status',snapshot(s),r.message+tip);return result();}
if(sub==='build'||sub==='建造'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}if(!s.atBase){seal.replyToSender(ctx,msg,'建造必须回到据点。先使用 .wjd action 返回。');return result();}const r=build(s,meta,arg(cmdArgs,2));let tip='';if(r.ok)tip=tutorialComplete(s,'build')+registerDailyAction(s,meta,'建造',{outside:false,eventChance:.08});write(uid,s);await image(ctx,msg,'base',{name:s.base.name,day:s.day,defense:s.base.defense,rooms:baseRooms(s),tip:r.msg},r.msg+tip);return result();}
if(sub==='base'||sub==='据点'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'base');write(uid,s);await image(ctx,msg,'base',{name:s.base.name,day:s.day,defense:s.base.defense,rooms:baseRooms(s),tip:'使用 .wjd build [编号] 建造设施。'},'据点蓝图已更新。'+tip);return result();}
if(sub==='relocate'||sub==='搬迁'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}if(!s.atBase){seal.replyToSender(ctx,msg,'搬迁前必须先返回当前据点整理物资。');return result();}const target=LOCATIONS[num(arg(cmdArgs,2))-1];if(!target){seal.replyToSender(ctx,msg,'搬迁目标请从地图编号中选择。');return result();}if(!hasInv(s,'零件',2)||!hasInv(s,'木板',2)){seal.replyToSender(ctx,msg,'搬迁需要木板×2、零件×2。');return result();}takeInv(s,'零件',2);takeInv(s,'木板',2);s.location=target.name;s.base.name=target.name;s.atBase=true;s.base.defense=Math.max(2,Math.floor((s.base.defense||0)*.65));s.base.condition=`刚搬来的临时据点：${target.kind}，风险 ${target.risk}。`;const warning=registerDailyAction(s,meta,'搬迁',{outside:false,eventChance:.2});write(uid,s);await image(ctx,msg,'base',{name:s.base.name,day:s.day,defense:s.base.defense,rooms:baseRooms(s),tip:`你把据点搬到了【${target.name}】。旧墙和旧路线都留在身后。`},'据点已迁移。'+warning);return result();}
if(sub==='map'||sub==='地图'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const page=Math.max(1,num(arg(cmdArgs,2),1)),tip=tutorialComplete(s,'map');write(uid,s);await image(ctx,msg,'map',{current:s.location,threat:s.threat,page,spots:LOCATIONS.map(x=>({name:x.name,kind:x.kind,risk:x.risk,current:x.name===s.location,locked:x.risk>s.threat+55}))},`地图第 ${page} 页。移动使用 .wjd action 移动 [地图编号]，搬迁使用 .wjd relocate [地图编号]。${tip}`);return result();}
if(sub==='weather'||sub==='天气'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'weather');write(uid,s);seal.replyToSender(ctx,msg,`【第${s.day}天天气：${s.weather.name}】\n${s.weather.desc}\n修正：${Object.keys(s.weather.mods||{}).map(k=>`${k}${s.weather.mods[k]>=0?'+':''}${s.weather.mods[k]}`).join('、')||'无'}${tip}`);return result();}
if(sub==='skills'||sub==='技能'||sub==='能力'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'skills');write(uid,s);await image(ctx,msg,'skills',{name:s.name,day:s.day,rows:skillRows(s)},'对应行动会积累技能经验。'+tip);return result();}
if(sub==='quests'||sub==='任务'||sub==='委托'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'quests');write(uid,s);await image(ctx,msg,'quests',{day:s.day,rows:questRows(s)},'每日生成三项委托，完成后自动发放奖励。'+tip);return result();}
if(sub==='survivors'||sub==='幸存者'||sub==='同伴'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'survivors');write(uid,s);await image(ctx,msg,'survivors',{name:s.name,day:s.day,rows:s.survivors||[]},(s.survivors.length?'同伴的职业会为据点提供长期加成。':'据点里目前只有你。使用 .wjd rescue 尝试营救。')+tip);return result();}
if(sub==='rescue'||sub==='营救'||sub==='招募'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const r=rescueSurvivor(s),tip=tutorialComplete(s,'rescue'),warning=registerDailyAction(s,meta,'营救',{outside:true,eventChance:.5});write(uid,s);await image(ctx,msg,'survivors',{name:s.name,day:s.day,rows:s.survivors||[]},r.msg+tip+warning);return result();}
if(sub==='goal'||sub==='目标'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const tip=tutorialComplete(s,'goal');write(uid,s);const plans=[{name:'修桥',desc:'找到市政蓝图、零件和足够的施工时间，让桥重新接上北岸。',need:`进度 ${s.escape.桥梁}%`,ready:s.escape.桥梁>=100},{name:'开车',desc:'修好一辆车，准备汽油，穿过封锁线。',need:`进度 ${s.escape.汽车}%`,ready:s.escape.汽车>=100},{name:'直升机救援',desc:'找到机场信号台和航空燃油，向仍在监听的人发出最后呼叫。',need:`进度 ${s.escape.直升机}%`,ready:s.escape.直升机>=100}];await image(ctx,msg,'escape',{threat:s.threat,progress:Math.max(s.escape.桥梁,s.escape.汽车,s.escape.直升机),plans},'用 .wjd action 出发 桥梁/汽车/直升机 推进计划。'+tip);return result();}
if(sub==='escape'||sub==='撤离'){if(!s||s.step!=='active'){seal.replyToSender(ctx,msg,'请先开始一个周目。');return result();}const names=['桥梁','汽车','直升机'];const n=num(arg(cmdArgs,2));const route=names[n-1]||arg(cmdArgs,2)||'桥梁';if(!s.escape[route]||s.escape[route]<100){seal.replyToSender(ctx,msg,`【${route}】还没有准备好。当前进度 ${s.escape[route]||0}%。`);return result();}s.dead=true;s.step='escaped';s.death={cause:`你通过【${route}】离开了围城。`,epitaph:'身后城市仍在燃烧，但你终于看见了没有高墙的天空。',achievements:s.milestones.concat(['成功撤离']),day:s.day};meta.runs++;meta.bestDay=Math.max(meta.bestDay,s.day);meta.points+=8+s.milestones.length;writeMeta(uid,meta);write(uid,s);await image(ctx,msg,'death',Object.assign({},s.death,{legacyPoints:meta.points,unlock:'成功撤离解锁：下一局可以从传承特质中挑选一项。'}),'撤离成功。周目已结算，传承点数已保存。');return result();}
